import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import java.util.regex.*;
import org.lwjgl.glfw.GLFW;
import org.lwjgl.opengl.*;
import net.irisshaders.iris.shaderpack.preprocessor.JcppProcessor;
import net.irisshaders.iris.helpers.StringPair;
public class ShaderCheck {
 static String include(ZipFile zip,String path,int depth)throws Exception{if(depth>35)throw new Exception("Include depth");ZipEntry e=zip.getEntry("shaders"+path);if(e==null)throw new Exception("Missing include "+path);String s=new String(zip.getInputStream(e).readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);Matcher m=Pattern.compile("(?m)^\\s*#include \\\"([^\\\"]+)\\\"[^\\r\\n]*").matcher(s);StringBuffer b=new StringBuffer();while(m.find()){String p=m.group(1);if(!p.startsWith("/"))p=path.substring(0,path.lastIndexOf('/')+1)+p;m.appendReplacement(b,Matcher.quoteReplacement(include(zip,p,depth+1)));}m.appendTail(b);return b.toString();}
 static void check(String source,String label)throws Exception{int shader=GL20.glCreateShader(GL20.GL_FRAGMENT_SHADER);GL20.glShaderSource(shader,source);GL20.glCompileShader(shader);String log=GL20.glGetShaderInfoLog(shader);if(GL20.glGetShaderi(shader,GL20.GL_COMPILE_STATUS)==0){Files.writeString(Path.of("work/failed-shader.glsl"),source);throw new Exception(label+"\n"+log);}GL20.glDeleteShader(shader);System.out.println("PASS "+label);}
 public static void main(String[] args)throws Exception{if(!GLFW.glfwInit())throw new Exception("GLFW init");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,GLFW.GLFW_FALSE);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MAJOR,4);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MINOR,3);GLFW.glfwWindowHint(GLFW.GLFW_OPENGL_PROFILE,GLFW.GLFW_OPENGL_COMPAT_PROFILE);long window=GLFW.glfwCreateWindow(32,32,"Shader validation",0,0);if(window==0)throw new Exception("GL window");GLFW.glfwMakeContextCurrent(window);GL.createCapabilities();System.out.println(GL11.glGetString(GL11.GL_RENDERER));
 String stub="#version 430 compatibility\n#define DEFERRED1\nuniform int isEyeInWater;uniform float sunVisibility,maxBlindnessDarkness,renderDistance;uniform mat4 gbufferModelViewInverse;uniform vec3 sunVec;vec3 cloudAmbientColor=vec3(.5),cloudLightColor=vec3(1);vec3 GetSky(float a,float b,float c,bool d,bool e){return vec3(.5);}float pow2(float x){return x*x;}\n";
 var defines=List.of(new StringPair("DISTANT_HORIZONS","1"),new StringPair("DH_BLOCK_WATER","1"),new StringPair("IS_IRIS","1"),new StringPair("IRIS_VERSION","11107"),new StringPair("MC_VERSION","260300"),new StringPair("MC_GL_VERSION","460"),new StringPair("MC_GLSL_VERSION","460"),new StringPair("MC_OS_WINDOWS","1"),new StringPair("MC_GL_VENDOR_NVIDIA","1"),new StringPair("MC_GL_RENDERER_GEFORCE","1"),new StringPair("MC_RENDER_QUALITY","1.0"),new StringPair("MC_SHADOW_QUALITY","1.0"),new StringPair("MC_HAND_DEPTH","0.125"));
 for(int i=1;i<args.length;i++)try(ZipFile zip=new ZipFile(args[i])){String properties=new String(zip.getInputStream(zip.getEntry("shaders/shaders.properties")).readAllBytes());
for(int mode:new int[]{50,3,4}){var modeDefines=new java.util.ArrayList<>(defines);modeDefines.add(new StringPair("CLOUD_STYLE_DEFINE",Integer.toString(mode)));String expanded=net.irisshaders.iris.shaderpack.preprocessor.PropertiesPreprocessor.preprocessSource(properties,modeDefines);var props=new java.util.Properties();props.load(new java.io.StringReader(expanded));String wanted=mode==50?"fancy":"off";if(!wanted.equals(props.getProperty("clouds")))throw new Exception("Wrong vanilla cloud routing for mode "+mode);if(props.getProperty("screen.CLOUD_SETTINGS","").contains("UNBOUND_SETTINGS")||props.getProperty("screen.CLOUD_SETTINGS","").contains("REIMAGINED_SETTINGS"))throw new Exception("Legacy submenu remains");System.out.println("PASS mode "+mode+" cloud suppression and menu");}
for(var entry:Collections.list(zip.entries())){if(!entry.getName().endsWith(".fsh")||entry.getName().contains("clrwl_"))continue;String source=include(zip,entry.getName().substring(7),0);if(!source.contains("float RidgeDensity")&&!entry.getName().endsWith("gbuffers_clouds.fsh"))continue;source=source.replace("#version 130","#version 430 compatibility");for(int mode:new int[]{50,3,4}){String variant=source.replace("#define CLOUD_STYLE_DEFINE 4 //[50 3 4]","#define CLOUD_STYLE_DEFINE "+mode+" //[50 3 4]");String out=JcppProcessor.glslPreprocessSource(variant,defines);if(entry.getName().equals("shaders/world0/deferred1.fsh")&&out.contains("float RidgeDensity")!=(mode==4)){Files.writeString(Path.of("work/mode-routing.glsl"),out);throw new Exception("Wrong cloud renderer for mode "+mode);}check(out,"mode "+mode+" "+entry.getName());}}}
 GLFW.glfwDestroyWindow(window);GLFW.glfwTerminate();}
}
